xhtml:div.script:
(function () {
  const BASE = "https://cdn.jsdelivr.net/gh/Zalecishavocwasmttaken/GameParadise@main/gameparadisemath/";
  async function launch(page) {
    const status = document.getElementById("status");
    // Open synchronously from the click so popup blockers are less likely to interfere.
    const tab = window.open("about:blank", "_blank");
    if (!tab) { status.textContent = "Popup blocked. Allow popups and try again."; return; }
    status.textContent = "Loading " + page + "...";
    try {
      const response = await fetch(BASE + page + "?t=" + Date.now());
      if (!response.ok) throw new Error("HTTP " + response.status);
      let html = await response.text();
      const baseTag = '<base href="' + BASE + '">';
      if (/<head(?:\s[^>]*)?>/i.test(html)) {
        html = html.replace(/<head(?:\s[^>]*)?>/i, function (head) { return head + "\n" + baseTag; });
      } else {
        html = "<head>" + baseTag + "</head>" + html;
      }
      if (tab.closed) throw new Error("The new tab was closed.");
      tab.document.open(); tab.document.write(html); tab.document.close();
      status.textContent = page + " launched.";
    } catch (error) {
      status.textContent = "Could not load " + page + ": " + error.message;
      if (!tab.closed) {
        tab.document.open();
        tab.document.write("<!doctype html><title>Launcher error</title><body style='background:#090f1a;color:white;font-family:Arial;padding:24px'><h2>Could not load " + page.replace(/[&<>\"]/g, "") + "</h2><p>" + String(error.message).replace(/[&<>\"]/g, "") + "</p></body>");
        tab.document.close();
      }
    }
  }
  document.getElementById("hubButton").addEventListener("click", function () { launch("hub.html"); });
  document.getElementById("gamesButton").addEventListener("click", function () { launch("games.html"); });
})();
